/* Bounded calendar with content-weighted period heights and independent cell scrolling. */
let calendarObserver=null,calendarFrame=null,calendarScrollTimer=null;
function calendarTags(t){const p=t.parent?parentOf(t):t;return `${assistance(t)?'<span class="task-token help">Help</span>':''}${(p.kind==='continuing'&&(p.subtype==='周期'||p.reminderOnly||continuous[p.id]?.interval>0))?`<span class="task-token recurring icon-token" role="img" aria-label="周期任务" title="周期任务">${icon('repeat')}</span>`:''}${t.person?`<span class="task-token offline icon-token" role="img" aria-label="需您线下参与" title="需您线下参与">${icon('person')}</span>`:''}`;}
personalTodo=function(t){return t.archive!=='archived'&&t.person===true&&!terminal(t.status)&&t.status!=='paused';};
function calendarName(t){return t.title.replace(/^\d{1,2}:\d{2}\s*/, '').replace(/ · (待您支付|需要登录邮箱|确认出发站)$/,'');}
workTimeline=function(){const dates=workDates(),events=workEvents(),today=new Date(now().getTime()+28800000).toISOString().slice(0,10);let html='<div class="timehead timecorner">时段</div>'+dates.map(d=>`<div class="timehead ${d===today?'today':''}" data-date="${d}">${d.slice(5).replace('-',' / ')}${d===today?' · 今天':''}<strong>周${['日','一','二','三','四','五','六'][new Date(d+'T12:00Z').getUTCDay()]}</strong></div>`).join('');['上午','下午','晚上'].forEach((label,period)=>{html+=`<div class="daypart" data-period="${period}">${label}</div>`;dates.forEach(date=>{const tasks=events.filter(t=>startDate(t)===date&&startPart(t)===period).sort((a,b)=>ts(startAt(a))-ts(startAt(b)));html+=`<div class="timecell ${date===today?'today':''}" data-period="${period}"><div class="period-scroll" tabindex="${tasks.length?'0':'-1'}" aria-label="${date}${label}，${tasks.length}个任务，全部展示"><div class="period-content">${tasks.map(t=>`<button class="timeitem ${t.status}" onclick="detail('${t.id}')" title="${esc(t.title)} · ${calendarStatus(t)}" aria-label="${esc(t.title)}，${calendarStatus(t)}"><div class="calendar-task-title"><strong>${esc(calendarName(t))}</strong><small class="calendar-status-text">${calendarStatus(t)}</small></div>${assistance(t)?`<div class="calendar-assistance"><span class="task-token help">Help</span><span>${esc(helpAction(t))}</span></div>`:''}<div class="calendar-meta"><small class="calendar-time">${fmt(startAt(t)).slice(-5)}</small>${calendarTags(t).replace(/<span class="task-token help">Help<\/span>/,'')}</div></button>`).join('')||'<span class="time-empty">—</span>'}</div></div></div>`;});});return `<section class="work-calendar adaptive-calendar"><div class="work-calendar-caption"><span class="calendar-caption-label">事情的时间表</span><div class="calendar-filters" role="group" aria-label="任务筛选">${[['all','全部'],['assist','需您确认'],['personal','需您在场']].map(([key,label])=>`<button class="${S.workFilter===key?'selected':''}" aria-pressed="${S.workFilter===key}" onclick="setWorkFilter('${key}')">${label}</button>`).join('')}</div></div><div id="work-timeline" class="work-timeline" tabindex="0" aria-label="任务时间表，默认当天，任务全部展示，可滑动和双指缩放"><div id="work-grid" class="timegrid" style="--n:${dates.length};--cw:${S.timelineWidth}px;grid-template-rows:40px repeat(3,minmax(90px,auto))">${html}</div></div><div class="work-legend color-legend"><div class="calendar-help"><button onclick="calendarTagHelp()">标识 ⓘ</button><small>横滑日期 · 双指缩放</small></div><div class="calendar-symbol-key"><span>${icon('repeat')} 周期</span><span>${icon('person')} 线下</span></div></div></section>`;};
function calendarTagHelp(){sheet('任务标识',`<p class="small"><span class="task-token help">Help</span> 需要您登录、确认、支付或补充信息。</p><p class="small"><span class="task-token offline">线下</span> 需要您本人到场或线下完成。</p><p class="small"><span class="task-token recurring">周期</span> 按固定节奏重复执行；时间表按日期展示每次实例。</p><p class="small muted">Help 和线下任务可同时存在：例如需要先确认参加地点，再到现场参会。标识说明参与方式，状态说明任务进度；一次性任务不加标识。</p>`);}
function allocatePeriods(needs,budget){const floor=Math.min(48,budget/3),heights=needs.map(n=>Math.min(n,floor));let remaining=Math.max(0,budget-heights.reduce((a,b)=>a+b,0));let active=needs.map((_,i)=>i).filter(i=>needs[i]>heights[i]);for(let pass=0;pass<4&&remaining>0.1&&active.length;pass++){const weights=active.map(i=>Math.sqrt(needs[i]-heights[i]));const total=weights.reduce((a,b)=>a+b,0);let spent=0;active.forEach((i,k)=>{const gain=Math.min(needs[i]-heights[i],remaining*weights[k]/total);heights[i]+=gain;spent+=gain;});remaining-=spent;active=active.filter(i=>needs[i]-heights[i]>0.1);}return heights.map(h=>Math.floor(h));}
function fitCalendar(){const sc=document.getElementById('work-timeline'),grid=document.getElementById('work-grid');if(!sc||!grid)return;grid.style.gridTemplateRows='40px repeat(3, minmax(90px, auto))';sc.style.height='auto';}
function helpAction(t){const q=(t.confirmations||[]).find(q=>!q.answer&&q.kind!=='offline');if(q?.actionLabel)return q.actionLabel;const text=(q?.question||'')+' '+(t.summary||'');if(/登录|授权/.test(text))return '请您登录';if(/支付|付款/.test(text))return '请您支付';if(/下单/.test(text))return '请您下单';if(/反馈/.test(text))return '请您反馈';if(/补充|提供|填写/.test(text))return '请您补充';if(t.status==='error')return '请您查看';return '请您确认';}
function requestCalendarFit(){if(calendarFrame)cancelAnimationFrame(calendarFrame);calendarFrame=requestAnimationFrame(()=>{calendarFrame=null;fitCalendar();});}
const previousCalendarBinding=bindWorkbenchGestures;
bindWorkbenchGestures=function(){calendarObserver?.disconnect();previousCalendarBinding();const sc=document.getElementById('work-timeline');if(!sc)return;requestCalendarFit();sc.addEventListener('scroll',()=>{clearTimeout(calendarScrollTimer);calendarScrollTimer=setTimeout(requestCalendarFit,100);},{passive:true});sc.addEventListener('touchmove',e=>{if(e.touches.length===2)requestCalendarFit();},{passive:true});sc.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey)requestCalendarFit();},{passive:true});if(typeof ResizeObserver!=='undefined'){calendarObserver=new ResizeObserver(requestCalendarFit);calendarObserver.observe(document.getElementById('main'));}};
window.addEventListener?.('resize',requestCalendarFit);
// A concrete case demonstrates that assistance and physical attendance are independent.
function addCombinedCase(){if(S.v11)return;const today=new Date(now().getTime()+28800000).toISOString().slice(0,10);const t={id:'case_offline_help',title:'到社区接种疫苗',theme:'小包成长',kind:'oneoff',status:'wait_user',person:true,source:'user',created:today+'T08:30',scheduledStart:today+'T16:00',summary:'请先确认预约时段；确认后仍需您带小包到社区接种。',quote:'帮我安排带小包到社区接种，先和我确认预约时间。',steps:[{title:'整理预约时段',status:'done',summary:'演示候选：今天 16:00 或明天 09:00。',at:fmt(today+'T08:30'),end:fmt(today+'T08:35')},{title:'确认后按约到场',status:'wait_user',summary:'需要您确认时段，并在当天带小包到场。'}],confirmations:[{id:'visit_time',at:today+'T08:35',question:'请选择计划到场的时段（演示，未实际预约）。',blocking:true,options:['今天 16:00','明天 09:00']}]};if(!item(t.id))S.items.push(t);S.v11=true;}
const priorCalendarInit=initWorkbench;
initWorkbench=function(){priorCalendarInit();addCombinedCase();};
const priorVisitAnswer=answerConfirmation;
answerConfirmation=function(id,qid,i){priorVisitAnswer(id,qid,i);if(qid==='visit_time'){const t=entity(id),d=new Date(now().getTime()+28800000+(i?86400000:0)).toISOString().slice(0,10);t.scheduledStart=d+(i?'T09:00':'T16:00');t.startedAt=null;t.status='todo';t.summary='已记录您选择的到场时段（演示）；届时仍需您带小包前往社区。';save();refreshPreserving();}};
frequency=function(t){return calendarTags(t);};
const CALENDAR_STATUS={done:'已完成',running:'在干活',todo:'待启动',wait_user:'需您协助',paused:'暂停',cancelled:'取消',error:'异常'};
function calendarStatus(t){return CALENDAR_STATUS[t.status]||'待启动';}
function fillViewportPeriods(needs,budget){const rows=allocatePeriods(needs,budget);const spare=Math.max(0,Math.floor(budget)-rows.reduce((a,b)=>a+b,0));const weights=needs.map(n=>Math.sqrt(Math.max(n,44))),sum=weights.reduce((a,b)=>a+b,0);let left=spare;rows.forEach((_,i)=>{const extra=i===2?left:Math.floor(spare*weights[i]/sum);rows[i]+=extra;left-=extra;});return rows;}
function ensureSwimming(){const stamp=now().getTime(),today=new Date(stamp+28800000).toISOString().slice(0,10);let root=item('swim_daily');if(!root){root={id:'swim_daily',title:'每天 19:00 提醒去游泳',theme:'生活照料',kind:'continuing',subtype:'周期',status:'running',person:true,reminderOnly:true,source:'user',created:today+'T08:00',quote:'每天下午七点提醒我去游泳。',summary:'每天 19:00 提醒；每一天单独记录是否已提醒，去游泳需要您本人完成。',steps:[{title:'安排每日提醒',status:'done',summary:'已建立每天 19:00 的演示计划。'},{title:'按日期发送提醒',status:'running',summary:'时间未到为待启动；模拟发出提醒后，本次提醒完成。'}],confirmations:[]};S.items.push(root);}if(root.status!=='running')return;
for(let offset=-2;offset<=6;offset++){const date=new Date(Date.parse(today+'T12:00Z')+offset*86400000).toISOString().slice(0,10),id='swim_'+date;if(inst(id))continue;const due=date+'T19:00',done=ts(due)<=stamp;S.instances.push({id,parent:root.id,title:'提醒去游泳',kind:'instance',person:true,reminderOnly:true,created:root.created,due,scheduledStart:due,status:done?'done':'todo',archive:done?'pending':null,summary:done?'已模拟发出 19:00 游泳提醒；不代表您已到场或完成游泳。':'19:00 到点提醒，去游泳需要您本人线下参与。',result:done?'本次游泳提醒已模拟发出；是否实际去游泳未核实。':'',confirmations:[]});}}
const preSwimInit=initWorkbench;
initWorkbench=function(){preSwimInit();ensureSwimming();};
const preSwimReconcile=reconcile;
reconcile=function(){let changed=false;for(const t of S.instances){if(t.reminderOnly&&!t.managedReminder&&t.status==='todo'&&item(t.parent)?.status==='running'&&ts(t.scheduledStart)<=now().getTime()){t.status='done';t.archive='pending';t.finished=now().toISOString();t.summary='已模拟发出游泳提醒；是否实际到场未核实。';t.result=t.summary;receipt(t,'19:00 的游泳提醒已发出（演示），本次提醒完成。','完成');changed=true;}}const previous=preSwimReconcile();if(changed)save();return previous||changed;};
const oldSwimPlan=planTable;
planTable=function(t){if(!t.reminderOnly)return oldSwimPlan(t);if(!t.parent)return oldSwimPlan(t);return `<section class="detail-section"><h3>本次提醒</h3><p>${fmt(t.scheduledStart)}</p><p>${t.status==='done'?'✓ 已模拟发出提醒':t.status==='todo'?'○ 到点后提醒':esc(STATUS[t.status])}</p><p class="small muted">完成的是提醒。游泳需要您本人参与，不代表已确认到场或完成运动。</p></section>`;};
// Recognize swipes over chat text AND task cards; keep native calendar gestures.
let pageSwipe=null,suppressSwipeClickUntil=0;
[document.getElementById('main'),document.querySelector('.top')].filter(Boolean).forEach(swipeSurface=>{
swipeSurface.addEventListener('touchstart',e=>{pageSwipe=null;if(e.touches.length!==1||e.target.closest('input,textarea,select,[contenteditable="true"],.work-calendar,.batch-grid,.digest-list,[data-no-page-swipe]'))return;pageSwipe={x:e.touches[0].clientX,y:e.touches[0].clientY,page:S.page,axis:null};},{passive:true});
swipeSurface.addEventListener('touchmove',e=>{if(e.touches.length!==1){pageSwipe=null;return;}if(!pageSwipe)return;const dx=e.touches[0].clientX-pageSwipe.x,dy=e.touches[0].clientY-pageSwipe.y;if(!pageSwipe.axis&&Math.max(Math.abs(dx),Math.abs(dy))>12)pageSwipe.axis=Math.abs(dx)>Math.abs(dy)*1.35?'x':'y';if(pageSwipe.axis==='x'&&e.cancelable)e.preventDefault();},{passive:false});
swipeSurface.addEventListener('touchend',e=>{if(!pageSwipe||!e.changedTouches.length)return;const p=pageSwipe;pageSwipe=null;const dx=e.changedTouches[0].clientX-p.x,dy=e.changedTouches[0].clientY-p.y;if(p.axis==='y'||Math.abs(dx)<50||Math.abs(dx)<Math.abs(dy)*1.35)return;const next=typeof adjacentPage==='function'?adjacentPage(p.page,dx):(p.page==='home'&&dx<0?'overview':p.page==='overview'&&dx>0?'home':null);if(next){suppressSwipeClickUntil=Date.now()+450;go(next);}},{passive:true});
swipeSurface.addEventListener('click',e=>{if(Date.now()<suppressSwipeClickUntil){e.preventDefault();e.stopImmediatePropagation();}},true);
swipeSurface.addEventListener('touchcancel',()=>pageSwipe=null,{passive:true});
});
S.timelineScroll=null;S.calendarZoomed=false;if(!S.v15){S.topicTab='all';S.workFolds={};S.timelineScroll=null;S.calendarZoomed=false;S.v15=true;}if(!S.v13){S.timelineScroll=null;S.calendarZoomed=false;S.page='home';S.v13=true;}initWorkbench();save();render();
